function setPath(target: Record<string, unknown>, path: string, value: string) {
  const parts = path.split(".");
  let cur = target;
  for (let i = 0; i < parts.length - 1; i += 1) {
    const key = parts[i];
    const next = cur[key];
    if (!next || typeof next !== "object") {
      cur[key] = {};
    }
    cur = cur[key] as Record<string, unknown>;
  }
  cur[parts[parts.length - 1]] = value;
}

export function getMessages(locale: Locale): Record<string, unknown> {
  const idx = Math.max(0, LOCALES.indexOf(locale));
  const nested: Record<string, unknown> = {};
  for (const [path, values] of Object.entries(rows)) {
    setPath(nested, path, values[idx] ?? values[0]);
  }
  nested.langs = LOCALE_LABELS_AS_DICT();
  return nested;
}

function LOCALE_LABELS_AS_DICT() {
  return {
    es: "Español",
    ca: "Català",
    eu: "Euskara",
    gl: "Galego",
    va: "Valencià",
    en: "English",
    fr: "Français",
    de: "Deutsch",
    it: "Italiano",
    pt: "Português",
    zh: "中文",
    ja: "日本語",
  };
}

export function flattenMessages(nested: Record<string, unknown>, prefix = ""): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [key, value] of Object.entries(nested)) {
    const path = prefix ? `${prefix}.${key}` : key;
    if (value && typeof value === "object") {
      Object.assign(out, flattenMessages(value as Record<string, unknown>, path));
    } else if (typeof value === "string") {
      out[path] = value;
    }
  }
  return out;
}
